import zipfile, sys, os
NS = 'xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"'
def run(t, b=False):
    t = t.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')
    rpr = '<w:rPr><w:b/></w:rPr>' if b else ''
    return f'<w:r>{rpr}<w:t xml:space="preserve">{t}</w:t></w:r>'
def para(text='', b=False, brk=False):
    return '<w:p>' + ('<w:r><w:br w:type="page"/></w:r>' if brk else '') + (run(text, b) if text else '') + '</w:p>'
def cell(tcw, text, b=False):
    tcW = f'<w:tcW w:w="{tcw[0]}" w:type="{tcw[1]}"/>' if tcw else ''
    return f'<w:tc><w:tcPr>{tcW}</w:tcPr>{para(text, b)}</w:tc>'
def table(grid, tcws, rows, tblw='<w:tblW w:w="0" w:type="auto"/>'):
    g = ''.join(f'<w:gridCol w:w="{w}"/>' for w in grid)
    trs = ''
    for ri, row in enumerate(rows):
        trs += '<w:tr>' + ''.join(cell(tcws[ci] if tcws else None, txt, ri == 0) for ci, txt in enumerate(row)) + '</w:tr>'
    return f'<w:tbl><w:tblPr><w:tblStyle w:val="TableGrid"/>{tblw}<w:tblLook w:val="04A0" w:firstRow="1" w:lastRow="0" w:firstColumn="1" w:lastColumn="0" w:noHBand="0" w:noVBand="1"/></w:tblPr><w:tblGrid>{g}</w:tblGrid>{trs}</w:tbl>'


